// Render returns an inline SVG icon for the given icon name and optional CSS class.
func Render(name, className string) template.HTML {
	spec, ok := registry[strings.TrimSpace(name)]
	if !ok {
		spec = registry["Code"]
	}
	cls := html.EscapeString(className)
	if spec.Stroke {
		return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="` + spec.ViewBox + `" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" class="` + cls + `">` + spec.Body + `</svg>`)
	}
	return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="` + spec.ViewBox + `" fill="currentColor" aria-hidden="true" class="` + cls + `">` + spec.Body + `</svg>`)
}

// ExperienceIcon picks the icon_name or returns a sensible fallback based on job title.
func ExperienceIcon(iconName, jobTitle string) string {
	if _, ok := registry[strings.TrimSpace(iconName)]; ok {
		return strings.TrimSpace(iconName)
	}
	lower := strings.ToLower(jobTitle)
	if strings.Contains(lower, "student") || strings.Contains(lower, "university") || strings.Contains(lower, "computer science") {
		return "LuGraduationCap"
	}
	if strings.Contains(lower, "intern") || strings.Contains(lower, "developer") || strings.Contains(lower, "engineer") || strings.Contains(lower, "support") {
		return "LuBriefcase"
	}
	return "MdWorkOutline"
}

// AvailableIcons returns all registered icons for admin form hints/datalists.
func AvailableIcons() []IconOption {
	order := []string{
		"SiPhp", "FaLaravel", "BiLogoJavascript", "SiTypescript", "RiTailwindCssFill",
		"FaReact", "SiNextdotjs", "SiGo", "SiPython", "SiKotlin", "SiFlutter", "SiNodedotjs",
		"DiGit", "SiMysql", "SiPostgresql", "Database",
		"BiLogoVisualStudio", "SiPostman", "SiJetbrains", "DiWindows", "AiOutlineLinux",
		"SiDocker", "SiGithub", "SiCloudflare", "SiNginx", "Terminal", "Server",
		"Music", "Book", "Gamepad", "Heart", "Camera", "Film", "Code", "Globe",
		"LuBriefcase", "LuGraduationCap", "MdWorkOutline",
	}
	out := make([]IconOption, 0, len(order))
	for _, k := range order {
		if spec, ok := registry[k]; ok {
			out = append(out, IconOption{
				Name:     k,
				Label:    spec.Label,
				Category: spec.Category,
			})
		}
	}
	return out
}
